btreact = 40;
minspin = 0.009;
ic=0;ir=0;ip=0;
colorrot =0;

code.perFrame:
zrot = zrot + zval;
yrot = yrot + yval;
xrot = xrot + xval;
zval = if(above(zval,minspin),zval - 0.0005,zval);
zval = if(above(minspin,zval),zval + 0.0005,zval);
xval = if(above(xval,minspin),xval - 0.0005,xval);
