yval = if(above(yval,minspin),yval - 0.0005,yval);
yval = if(above(minspin,yval),yval + 0.0005,yval);
ic = 0;ir = 0;ip = 0;
colorrot = colorrot + 0.1;
colorrot = if(above(abs(colorrot),2*$PI),0,colorrot);

code.onBeat:
xval = xval + rand(100)/btreact;
yval = yval + rand(100)/btreact;
zval = zval + rand(100)/btreact;
xval = if(above(xval,0.03),0.03,xval);
xval = if(above(-0.03,xval),-0.03,xval);
yval = if(above(yval,0.03),0.03,yval);
yval = if(above(-0.03,yval),-0.03,yval);
zval = if(above(zval,0.03),0.03,zval);
